\dfrac{1}{1998}S &= \dfrac{1}{1998}+2\left(\dfrac{1}{1998}\right)^2+3\left(\dfrac{1}{1998}\right)^3+\cdots\\
\end{align*}
Subtracting the second equation from the first, we get
\begin{align*}
S - \dfrac{1}{1998}S &= 1+\left(\dfrac{1}{1998}\right)+\left(\dfrac{1}{1998}\right)^2+\left(\dfrac{1}{1998}\right)^3+\cdots\\
\dfrac{1997}{1998}S &= 1+\dfrac{1}{1998}+\dfrac{1}{1998^2}+\dfrac{1}{1998^3}+\cdots\\
\end{align*}
